def vertical_mirror_and_complete(grid):
    result = [[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                result[i][j] = grid[i][j]
                # Mirror vertically across row 3 (center)
                result[6-i][j] = grid[i][j]
    return result

