def mirror_top_bottom(grid):
    result = [[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                result[i][j] = grid[i][j]
    # Mirror rows 0-3 to 6-3
